/// A place in Settings the Shell can send the user to. A capability, not a
/// tab index: the per-OS row id stays in the consent catalog.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Reveal {
    WindowNamesConsent,
    /// The AI source picker, for the Chat landing's button that offers a
    /// source other than the branded Harnesses.
    AiSource,
}

/// Where to send the page. The tab is its title, which `selectTab` already takes.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
pub struct RevealTarget {
    pub tab: String,
    pub row: String,
    pub focus: RevealFocus,
}

/// What takes the focus in the row. A picker shows its ring on the control.
/// A consent row takes the focus itself, so a stray Space cannot grant.
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "lowercase")]
pub enum RevealFocus {
    Control,
    Row,
}

impl Reveal {
    /// Names the row to draw attention to. Checking a consent box stays the user's.
    pub fn target(self) -> RevealTarget {
        match self {
            Self::WindowNamesConsent => {
                let row = consent::rows(|_| false)
                    .into_iter()
                    .find(|row| row.id == consent::CapabilityId::WindowNames)
                    .map(|row| row.row_id())
                    .expect("WindowNames is in the consent catalog");
                RevealTarget {
                    tab: "Privacy".to_string(),
                    row,
                    focus: RevealFocus::Row,
                }
            }
            Self::AiSource => RevealTarget {
                tab: "AI".to_string(),
                row: HARNESS_ID.to_string(),
                focus: RevealFocus::Control,
            },
        }
    }
}

/// The two Completer-source titles the file does not spell the same way: Model
/// API (wire: empty string) and Harness · Custom (wire: `custom`), which
/// defers to the command line beside it.
pub const HARNESS_OFF: &str = "Model API";
pub const HARNESS_CUSTOM: &str = "Harness · Custom";
/// What `harness_choice` writes for Custom. Not a value `FIDGET_HARNESS`
/// can take, so it cannot collide with a Harness of that name.
pub const HARNESS_CUSTOM_VALUE: &str = "custom";
/// The named launch rows, in ADR-0022's order.
pub const HARNESS_PRESETS: [&str; 10] = [
    "claude",
    "codex",
    "copilot",
    "cursor-agent",
    "goose",
    "grok",
    "hermes",
    "opencode",
    "pi",
    "antigravity",
];

/// The endpoints the Base URL picker names, as (group, name, host). vLLM and
/// `mlx_lm.server` get no row: they answer on oMLX's 8000 and llama.cpp's 8080,
/// so a row would be a second name for a URL already listed.
const ENDPOINTS: &[(&str, &str, &str)] = &[
    ("Local", "Ollama", "http://localhost:11434"),
    ("Local", "LM Studio", "http://localhost:1234"),
    ("Local", "oMLX", "http://localhost:8000"),
    ("Local", "llama.cpp", "http://localhost:8080"),
    ("Hosted", "OpenAI", "https://api.openai.com"),
    ("Hosted", "Anthropic", "https://api.anthropic.com"),
    ("Hosted", "xAI", "https://api.x.ai"),
];

/// The title a fill-in-the-field picker rests on for a value it does not name
/// — a base URL off the list, or a reasoning effort off it. Picking it writes
/// nothing: the field beside it is what the custom value is.
pub const PICKER_CUSTOM: &str = "Custom";

fn endpoint_title_of(_group: &str, name: &str, url: &str) -> String {
    format!("{name} ({url})")
}

/// The Base URL picker's choices, Custom first. No header rows: GTK draws these
/// as a radio group, where an inert header is a click that silently does
/// nothing. Order carries the grouping instead, local servers first.
pub fn endpoint_options() -> Vec<String> {
    let mut options = vec![PICKER_CUSTOM.to_string()];
    options.extend(
        ENDPOINTS
            .iter()
            .map(|(group, name, url)| endpoint_title_of(group, name, url)),
    );
    options
}

/// The base URL a picked title means, or `None` for Custom and for a title off
/// the list — neither of which is a value to write over what the field holds.
pub fn endpoint_url(title: &str) -> Option<&'static str> {
    ENDPOINTS
        .iter()
        .find(|(group, name, url)| endpoint_title_of(group, name, url) == title)
        .map(|(_, _, url)| *url)
}

/// The title to rest on for the base URL in force. The inverse of
/// `endpoint_url`, and Custom for the endpoints this list does not name —
/// which is most of what the field can hold.
pub fn endpoint_title(base_url: &str) -> String {
    let base_url = base_url.trim().trim_end_matches('/');
    ENDPOINTS
        .iter()
        .find(|(_, _, url)| *url == base_url)
        .map(|(group, name, url)| endpoint_title_of(group, name, url))
        .unwrap_or_else(|| PICKER_CUSTOM.to_string())
}

/// The three effort levels every documented host takes. Beyond them hosts
/// disagree (xAI lacks `max`, Ollama `xhigh`), so the free field beside the
/// picker covers the rest.
const EFFORT_LEVELS: [&str; 3] = ["low", "medium", "high"];

/// The reasoning-effort picker's choices, Custom first, exactly as the Base
/// URL picker is shaped: the field beside it is the setting, and the picker
/// only fills it in.
pub fn effort_options() -> Vec<String> {
    let mut options = vec![PICKER_CUSTOM.to_string()];
    options.extend(EFFORT_LEVELS.iter().map(|level| level.to_string()));
    options
}

/// The level a picked title means, or `None` for Custom — which writes
/// nothing, because the field is what a level off this list is.
pub fn effort_value(title: &str) -> Option<&'static str> {
    EFFORT_LEVELS.iter().find(|level| **level == title).copied()
}

/// The title to rest on for the level in force. Custom for anything the
/// picker does not name, blank included: blank is `low` by default, not by a
/// pick, and resting on `low` would offer to un-set it as an edit.
pub fn effort_title(effort: &str) -> String {
    match effort_value(effort.trim()) {
        Some(level) => level.to_string(),
        None => PICKER_CUSTOM.to_string(),
    }
}

/// The Completer-source popup's choices, in the order it draws them.
pub fn harness_options() -> Vec<String> {
    let mut options = vec![HARNESS_OFF.to_string()];
    options.extend(
        HARNESS_PRESETS
            .iter()
            .map(|name| format!("Harness · {}", name)),
    );
    options.push(HARNESS_CUSTOM.to_string());
    options
}

/// The popup title for a source in force, and the command line beside it.
/// `FIDGET_HARNESS` puts a custom command in the value; the file keeps `custom`
/// plus its own field.
pub fn harness_rows(value: &str, command: &str) -> (String, String) {
    match value.trim() {
        "" => (HARNESS_OFF.to_string(), command.to_string()),
        HARNESS_CUSTOM_VALUE => (HARNESS_CUSTOM.to_string(), command.to_string()),
        preset if HARNESS_PRESETS.contains(&preset) => {
            (format!("Harness · {}", preset), command.to_string())
        }
        line => (HARNESS_CUSTOM.to_string(), line.to_string()),
    }
}

/// The command line a source value carries in the value itself, as
/// `FIDGET_HARNESS` or a hand-edited file may. `Settings::apply` moves it to
/// the row that owns it.
pub fn harness_command_line(value: &str) -> Option<&str> {
    match value.trim() {
        "" | HARNESS_CUSTOM_VALUE => None,
        preset if HARNESS_PRESETS.contains(&preset) => None,
        line => Some(line),
    }
}

/// What a popup title means in the file. The inverse of `harness_rows`.
pub fn harness_choice(title: &str) -> String {
    match title {
        HARNESS_OFF => String::new(),
        HARNESS_CUSTOM => HARNESS_CUSTOM_VALUE.to_string(),
        title if title.starts_with("Harness · ") => title
            .strip_prefix("Harness · ")
            .unwrap_or(title)
            .to_string(),
        preset => preset.to_string(),
    }
}

pub fn chat_ui_choice(title: &str) -> String {
    match title {
        "Minimal" => "minimal".to_string(),
        "Terminal" => "terminal".to_string(),
        "Glass" => "glass".to_string(),
        _ => "minimal".to_string(),
    }
}

pub fn chat_ui_title(value: &str) -> String {
    match value {
        "minimal" => "Minimal".to_string(),
        "terminal" => "Terminal".to_string(),
        "glass" => "Glass".to_string(),
        _ => "Minimal".to_string(),
    }
}

/// (label, frozen, status) for a text row an environment variable can own: the
/// Director endpoint and the Completer limits, which take any exported value.
fn env_row_parts(label: &str, var: &str) -> (String, bool, Option<String>) {
    owned_row_parts(label, var, model::env_override(var).is_some())
}

/// The same question for a row holding a switch, which answers to a narrower
/// set of values: one `model::env_switch` cannot read owns nothing, so the row
/// stays the user's rather than freezing over a value nobody obeyed.
fn switch_row_parts(label: &str, var: &str) -> (String, bool, Option<String>) {
    owned_row_parts(label, var, model::env_switch(var).is_some())
}

/// Returns (label, frozen, status) for a row that may be owned by the environment.
fn owned_row_parts(label: &str, var: &str, owned: bool) -> (String, bool, Option<String>) {
    match owned {
        true => (
            label.to_string(),
            true,
            Some(format!("Overridden by env: {var}")),
        ),
        false => (label.to_string(), false, None),
    }
}

/// (label, frozen, status) for the Completer source rows. Any export owns them,
/// empty included: `harness::from_settings` reads empty as Off, so an editable
/// row would take an edit the launch discards.
fn harness_env_row_parts(label: &str) -> (String, bool, Option<String>) {
    let var = crate::harness::VAR;
    let owned = std::env::var_os(var).is_some();
    owned_row_parts(label, var, owned)
}

/// A checkbox for one development switch, frozen when `model::env_switch`
/// reads the exported value, since that value is the switch.
fn flag_row(
    id: &str,
    flag: &dev_flags::Flag,
    writes: BoolField,
    label: &str,
    help: &str,
) -> FormRow {
    let (label, frozen, status) = switch_row_parts(label, flag.var());
    FormRow::Checkbox {
        id: id.to_string(),
        label,
        writes,
        batched: false,
        frozen,
        help: Some(help.to_string()),
        comment: None,
        disclosure: None,
        status,
    }
}

