    /// The snapshot with the tabs this platform does not build the same way
    /// dropped, so one pair of fixtures serves all three.
    fn pinned_tabs(mut value: serde_json::Value) -> serde_json::Value {
        let tabs = value["tabs"].as_array().expect("tabs is an array").clone();
        value["tabs"] = tabs
            .into_iter()
            .filter(|tab| !UNPINNED_TABS.contains(&tab["title"].as_str().unwrap_or_default()))
            .collect();
        value
    }

    /// The page renders these two files, so they are the interface between the
    /// Rust description and the JavaScript. Compared, never written: an unmeant
    /// `form.rs` edit has to reach CI as a fixture diff.
    #[test]
    fn both_ai_sources_serialize_to_the_committed_fixtures() {
        const FIXTURES: [(&str, &str, bool); 2] = [
            (
                "settings-snapshot-modelApi.json",
                include_str!("../../../tests/fixtures/settings-snapshot-modelApi.json"),
                false,
            ),
            (
                "settings-snapshot-harnessDriving.json",
                include_str!("../../../tests/fixtures/settings-snapshot-harnessDriving.json"),
                true,
            ),
        ];
        // The Director and Development variables decide half these rows, and a
        // developer's exported one would otherwise rewrite the fixture.
        crate::model::tests::with_env(None, None, None, || {
            for (name, committed, driving) in FIXTURES {
                let expected = pinned_tabs(
                    serde_json::from_str(committed).expect("the fixture has to be JSON"),
                );
                let actual = pinned_tabs(
                    serde_json::to_value(describe_with(&fixture_live(driving)))
                        .expect("the description has to serialize"),
                );
                if actual != expected {
                    let dump = std::env::temp_dir().join(name);
                    let _ = std::fs::write(
                        &dump,
                        serde_json::to_string_pretty(&actual).unwrap_or_default(),
                    );
                    panic!(
                        "tests/fixtures/{name} no longer matches form::describe_with. \
                         What the form produces now is at {}; diff it, and commit it \
                         with the change that moved it.",
                        dump.display()
                    );
                }
            }
        });
    }

    /// Every row id the page looks a value up by, on the tabs these fixtures
    /// pin. One key per row; a button and a secure field carry no value.
    fn value_row_ids(
        description: &FormDescription,
        skip: &[&str],
    ) -> std::collections::BTreeSet<String> {
        let mut ids = std::collections::BTreeSet::new();
        for tab in &description.tabs {
            if skip.contains(&tab.title.as_str()) {
                continue;
            }
            for row in tab.sections.iter().flat_map(|section| section.rows.iter()) {
                match row {
                    FormRow::Composite { controls, .. } => {
                        for control in controls {
                            match control {
                                CompositeControl::Button { .. } => {}
                                CompositeControl::TextField { id, .. }
                                | CompositeControl::Popup { id, .. } => {
                                    ids.insert(id.clone());
                                }
                            }
                        }
                    }
                    // A secure row carries its placeholder and no value: the
                    // secret never leaves the store.
                    FormRow::SecureField { .. } => {}
                    FormRow::Checkbox { id, .. }
                    | FormRow::TextField { id, .. }
                    | FormRow::InspectBlock { id, .. }
                    | FormRow::InspectPath { id }
                    | FormRow::Popup { id, .. }
                    | FormRow::Multiline { id, .. }
                    | FormRow::List { id, .. } => {
                        ids.insert(id.clone());
                    }
                }
            }
        }
        ids
    }

    /// A row whose value is this machine's rather than the file's: the hotkey
    /// reads in the OS's key names, so a macOS fixture cannot hold a Windows
    /// build's text. The key set is still pinned everywhere.
