    #[test]
    fn the_consent_section_has_a_checkbox_per_grant_this_platform_offers() {
        let description = describe();
        let consent = description
            .sections()
            .find(|s| s.heading == "What the fidget can see")
            .expect("Consent section exists");

        #[cfg(target_os = "macos")]
        {
            assert_eq!(consent.rows.len(), 3);
            let listed = crate::consent::process_listed_as();
            assert!(
                consent
                    .comment
                    .as_ref()
                    .is_some_and(|c| { c.contains(&listed) && c.contains("Privacy & Security") }),
                "Consent section has to name the TCC row ({listed}), got {:?}",
                consent.comment
            );

            let accessibility = consent
                .rows
                .iter()
                .find(
                    |r| matches!(r, FormRow::Checkbox { id, .. } if id == CONSENT_ACCESSIBILITY_ID),
                )
                .expect("Accessibility checkbox exists");

            let window_titles = consent
                .rows
                .iter()
                .find(
                    |r| matches!(r, FormRow::Checkbox { id, .. } if id == CONSENT_SCREEN_RECORDING_ID),
                )
                .expect("Window names checkbox exists");

            match accessibility {
                FormRow::Checkbox { label, help, .. } => {
                    assert_eq!(label, "Accessibility");
                    assert!(
                        help.as_ref().is_some_and(|h| h.contains("Dock")),
                        "Accessibility help should mention Dock"
                    );
                }
                _ => panic!("Accessibility row must be a checkbox"),
            }

            match window_titles {
                FormRow::Checkbox {
                    label,
                    help,
                    disclosure,
                    ..
                } => {
                    assert_eq!(label, "Window and application names");
                    assert_eq!(help.as_deref(), Some("Requires macOS Screen Recording."));
                    assert_eq!(
                        disclosure.as_deref(),
                        Some("macOS Screen Recording lets your fidget read window titles. Fidget does not capture the screen. One switch covers titles and application names alike, so with it off fidget knows where the windows are and not what they are; the sprite lands on them either way. With it on, list_windows, describe_screen and the readonly MCP resource report the owning application and the title.")
                    );
                }
                _ => panic!("Window names row must be a checkbox"),
            }

            // The compiler pins each of these to *a* bool; only the test pins it
            // to the right one, and a swap here would grant the other capability.
            assert_eq!(
                description.bool_write(CONSENT_ACCESSIBILITY_ID),
                Some(BoolField::UseAccessibility)
            );
            assert_eq!(
                description.bool_write(CONSENT_SCREEN_RECORDING_ID),
                Some(BoolField::UseWindowNames)
            );

            let input_monitoring = consent
                .rows
                .iter()
                .find(
                    |r| matches!(r, FormRow::Checkbox { id, .. } if id == CONSENT_INPUT_MONITORING_ID),
                )
                .expect("Input Monitoring checkbox exists");

            match input_monitoring {
                FormRow::Checkbox {
                    label, disclosure, ..
                } => {
                    assert_eq!(label, "Input Monitoring");
                    let disclosure = disclosure
                        .as_ref()
                        .expect("the row explains the grant before it is asked for (#721)");
                    assert!(
                        disclosure.contains("mouse"),
                        "the disclosure has to say the tap is mouse-only, got {disclosure:?}"
                    );
                    assert!(
                        disclosure.contains("keyboard"),
                        "the disclosure has to say the tap cannot see the keyboard, got {disclosure:?}"
                    );
                }
                _ => panic!("Input Monitoring row must be a checkbox"),
            }

            assert_eq!(
                description.bool_write(CONSENT_INPUT_MONITORING_ID),
                Some(BoolField::UseInputMonitoring)
            );
        }

        #[cfg(not(target_os = "macos"))]
        {
            let comment = consent
                .comment
                .as_ref()
                .expect("Non-macOS section has prose when rows are omitted");
            assert!(
                !comment.contains("Accessibility"),
                "Non-macOS prose must not use TCC vocabulary, got {comment:?}"
            );
            assert!(
                !comment.contains("Screen Recording"),
                "Non-macOS prose must not use TCC vocabulary, got {comment:?}"
            );
            assert!(
                !comment.contains("Privacy & Security"),
                "Non-macOS prose must not use TCC vocabulary, got {comment:?}"
            );

            #[cfg(target_os = "linux")]
            {
                assert_eq!(consent.rows.len(), 1);
                let portal_screencast = consent
                    .rows
                    .iter()
                    .find(|r| {
                        matches!(r, FormRow::Checkbox { id, .. } if id == CONSENT_PORTAL_SCREENCAST_ID)
                    })
                    .expect("PortalScreenCast checkbox exists");

                assert!(
                    matches!(portal_screencast, FormRow::Checkbox { label, .. } if label == "Window and application names"),
                    "Linux ScreenCast checkbox label must name what it buys, got {:?}",
                    portal_screencast
                );

                assert!(
                    comment.contains("portal") || comment.contains("Portal"),
                    "Linux prose must mention the portal, got {comment:?}"
                );
                assert!(
                    comment.contains("window") || comment.contains("Window"),
                    "Linux prose must name what is read without a grant, got {comment:?}"
                );
            }

            #[cfg(target_os = "windows")]
            {
                assert_eq!(consent.rows.len(), 1, "Windows has WindowNames only");
                assert!(
                    !comment.contains("macOS"),
                    "Windows prose must not mention macOS, got {comment:?}"
                );
            }
        }
    }

    fn development_tab(description: &FormDescription) -> &FormTab {
        description
            .tabs
            .iter()
            .find(|tab| tab.title == "Development")
            .expect("the Development tab exists")
    }

    fn row_id(row: &FormRow) -> Option<&str> {
        match row {
            FormRow::Checkbox { id, .. }
            | FormRow::TextField { id, .. }
            | FormRow::Composite { id, .. } => Some(id.as_str()),
            _ => None,
        }
    }

