    /// A switch the env owns names its variable and takes no click. A value the
    /// vocabulary reads freezes the row, `0` included; one it cannot read owns
    /// nothing, since freezing would claim an export the switch never obeyed.
    #[test]
    fn an_env_owned_flag_row_is_frozen_and_names_its_variable() {
        crate::model::tests::with_env(None, None, None, || {
            let var = dev_flags::TRACE_FRAMES.var();
            for (exported, owned) in [
                (Some("1"), true),
                (Some("0"), true),
                (Some("true"), true),
                (Some("banana"), false),
                (None, false),
            ] {
                match exported {
                    Some(value) => std::env::set_var(var, value),
                    None => std::env::remove_var(var),
                }
                let description = describe();

                let row = development_tab(&description)
                    .sections
                    .iter()
                    .flat_map(|section| &section.rows)
                    .find(|row| row_id(row) == Some(TRACE_FRAMES_ID))
                    .expect("the trace-frames row exists");

                match row {
                    FormRow::Checkbox {
                        label,
                        frozen,
                        status,
                        ..
                    } => {
                        assert_eq!(*frozen, owned, "exported {exported:?} decides the click");
                        assert_eq!(
                            status.is_some() && status.as_ref().unwrap().contains(var),
                            owned,
                            "exported {exported:?} decides the status, got label={label:?}, status={status:?}"
                        );
                    }
                    _ => panic!("the trace-frames row is a checkbox"),
                }
            }
            std::env::remove_var(var);
        });
    }

