    /// Model API blank is one number. The Harness budget is the other row.
    #[test]
    fn a_blank_model_api_timeout_is_thirty_seconds() {
        let description = describe();
        let dev_tab = development_tab(&description);
        let placeholder = dev_tab
            .sections
            .iter()
            .flat_map(|section| &section.rows)
            .find_map(|row| match row {
                FormRow::TextField {
                    id, placeholder, ..
                } if id == DIRECTOR_TIMEOUT_SECS_ID => Some(placeholder.clone()),
                _ => None,
            })
            .expect("the timeout row carries a placeholder");

        assert_eq!(placeholder, "30");

        let disclosure = dev_tab
            .sections
            .iter()
            .find_map(|section| {
                if section.rows.iter().any(|row| {
                    matches!(row, FormRow::TextField { id, .. } if id == DIRECTOR_TIMEOUT_SECS_ID)
                }) {
                    section.disclosure.clone()
                } else {
                    None
                }
            })
            .expect("the timeout section carries disclosure");

        assert!(
            disclosure.contains("Model API"),
            "the disclosure must say which brain this row budgets, got {disclosure:?}"
        );
        assert!(
            disclosure.contains("Leave empty"),
            "empty-field copy has to name what the user does, not Blank, got {disclosure:?}"
        );
        assert!(
            disclosure.contains("fallback to default behavior"),
            "expiry has to be user terms, not Static, got {disclosure:?}"
        );
        assert!(
            !disclosure.contains("session/prompt"),
            "a Harness turn is the other row, got {disclosure:?}"
        );
    }

