    /// `harness::retarget` makes every pick live, so copy asking for a restart
    /// is wrong.
    #[test]
    fn no_completer_source_copy_promises_a_relaunch() {
        crate::model::tests::with_harness(None, || {
            let section = completer_source_section();
            let mut copy = section.comment.clone().unwrap_or_default();
            for row in &section.rows {
                if let FormRow::Popup { help, .. } | FormRow::InspectBlock { help, .. } = row {
                    copy.push(' ');
                    copy.push_str(help.as_deref().unwrap_or_default());
                }
            }
            assert!(
                !copy.to_lowercase().contains("next launch")
                    && !copy.to_lowercase().contains("restart"),
                "got {copy:?}"
            );
        });
    }

    /// Pick and blur do not retarget. The disclosure has to name Apply
    /// so the row and the button cannot disagree about when the child dies.
    #[test]
    fn the_source_rows_say_apply_commits() {
        crate::model::tests::with_harness(None, || {
            let section = completer_source_section();
            let mut copy = section.disclosure.clone().unwrap_or_default();
            for row in &section.rows {
                if let FormRow::Popup { disclosure, .. } | FormRow::TextField { disclosure, .. } =
                    row
                {
                    copy.push(' ');
                    copy.push_str(disclosure.as_deref().unwrap_or_default());
                }
            }
            let lower = copy.to_lowercase();
            assert!(
                !lower.contains("every pick takes effect") && !lower.contains("blur commits"),
                "got {copy:?}"
            );
            assert!(lower.contains("apply"), "got {copy:?}");
            let description = describe();
            assert!(description.batched(HARNESS_ID));
            assert!(description.batched(HARNESS_COMMAND_ID));
        });
    }

    /// Model API (the Off choice) means HTTP Completer, not static weights.
    /// Static weights is AI on off (the DIRECTOR_ENABLED switch).
    #[test]
    fn completer_source_does_not_equate_model_api_with_static_weights() {
        crate::model::tests::with_harness(None, || {
            let section = completer_source_section();
            let mut copy = section.comment.clone().unwrap_or_default();
            copy.push(' ');
            copy.push_str(&section.disclosure.clone().unwrap_or_default());
            for row in &section.rows {
                if let FormRow::Popup {
                    help, disclosure, ..
                } = row
                {
                    copy.push(' ');
                    copy.push_str(help.as_deref().unwrap_or_default());
                    copy.push(' ');
                    copy.push_str(disclosure.as_deref().unwrap_or_default());
                }
            }
            let lower = copy.to_lowercase();
            assert!(
                !lower.contains("off: static weights")
                    && !lower.contains("off (static weights)")
                    && !(lower.contains("off") && lower.contains("static weights only")),
                "Model API should not be described as static weights; that is AI on off. Got: {copy:?}"
            );
        });
    }

    /// The Advanced rows in reading order: pick the Harness, copy the box,
    /// follow the words. Always 6: the token field and its Copy hide when
    /// empty.
    #[test]
    fn the_byo_section_picks_a_harness_then_shows_the_snippet() {
        let description = describe();
        let section = description
            .sections()
            .find(|s| s.heading == BYO_HEADING)
            .expect("the Harness registration section");

        assert_eq!(section.rows.len(), 6, "BYO section always emits 6 rows");

        assert!(matches!(
            section.rows[0],
            FormRow::Popup { ref id, ref options, frozen: false, .. }
                if id == BYO_HARNESS_ID && options.len() == HARNESS_PRESETS.len()
        ));
        assert!(matches!(
            section.rows[1],
            FormRow::InspectBlock { ref id, .. } if id == BYO_SNIPPET_ID
        ));
        assert!(matches!(
            section.rows[2],
            FormRow::Composite { ref controls, .. }
                if matches!(
                    controls.as_slice(),
                    [CompositeControl::Button { id, frozen: false, .. }] if id == BYO_COPY_ID
                )
        ));
        assert!(matches!(
            section.rows[3],
            FormRow::InspectBlock { ref id, .. } if id == BYO_TOKEN_ID
        ));
        assert!(matches!(
            section.rows[4],
            FormRow::Composite { ref controls, .. }
                if matches!(
                    controls.as_slice(),
                    [CompositeControl::Button { id, frozen: false, .. }] if id == BYO_COPY_TOKEN_ID
                )
        ));
        assert!(matches!(
            section.rows[5],
            FormRow::InspectBlock { ref id, .. } if id == BYO_STEPS_ID
        ));
    }

    /// Both Character popups offer every installed package, not only the one
    /// in force, because the webview only sees the description.
    #[test]
    fn both_character_popups_offer_the_installed_packages() {
        let description = describe_with(&fixture_live(false));
        let rows: Vec<&FormRow> = description
            .sections()
            .flat_map(|section| section.rows.iter())
            .collect();
        let character = rows.iter().find_map(|row| match row {
            FormRow::Popup { id, options, .. } if id == CHARACTER_ID => Some(options.clone()),
            _ => None,
        });
        let new_character = rows.iter().find_map(|row| match row {
            FormRow::Composite { controls, .. } => controls.iter().find_map(|c| match c {
                CompositeControl::Popup { id, options, .. } if id == NEW_CHARACTER_ID => {
                    Some(options.clone())
                }
                _ => None,
            }),
            _ => None,
        });
        assert_eq!(
            character.as_deref(),
            Some(&["bmo".to_string(), "ghost".to_string()][..])
        );
        assert_eq!(new_character, character);
    }

    /// `byo_section` does not read the settings document, so asserting these
    /// rows must not write one either: a stray save would wipe the user's real
    /// Harness.
    #[test]
    fn describing_the_form_does_not_rewrite_the_user_settings_file() {
        let path = crate::settings::settings_path(&fidget_core::memory::data_dir());
        let before = std::fs::read(&path).ok();

        let description = describe_with(&fixture_live(false));
        let section = description
            .sections()
            .find(|s| s.heading == BYO_HEADING)
            .expect("the Harness registration section");
        assert!(
            section
                .rows
                .iter()
                .any(|row| matches!(row, FormRow::InspectBlock { id, .. } if id == BYO_TOKEN_ID)),
            "the token InspectBlock is always present"
        );
        assert!(
            section.rows.iter().any(|row| {
                matches!(row, FormRow::Composite { controls, .. } if controls.iter().any(|c| {
                    matches!(c, CompositeControl::Button { id, .. } if id == BYO_COPY_TOKEN_ID)
                }))
            }),
            "the copy token button is always present"
        );

        let after = std::fs::read(&path).ok();
        assert_eq!(
            before, after,
            "describing the form must not create or rewrite the user settings document"
        );
    }

    /// The one thing a user cannot work out from the box: yesterday's paste
    /// stopped working because both halves of it are new every launch.
    #[test]
    fn the_byo_box_says_the_token_changes_every_launch() {
        let description = describe();
        let help = description
            .sections()
            .flat_map(|section| &section.rows)
            .find_map(|row| match row {
                FormRow::InspectBlock { id, help, .. } if id == BYO_SNIPPET_ID => help.clone(),
                _ => None,
            })
            .unwrap_or_default();
        assert!(
            help.contains("launch"),
            "the snippet's help must date the snippet, got {help:?}"
        );
    }

    /// Off and Custom are the attach popup's grammar, not this one's: this box
    /// registers fidget with a Harness the user starts themselves, and
    /// neither of those names one.
    #[test]
    fn the_byo_picker_offers_only_the_named_harnesses() {
        let description = describe();
        let options = description
            .sections()
            .flat_map(|section| &section.rows)
            .find_map(|row| match row {
                FormRow::Popup { id, options, .. } if id == BYO_HARNESS_ID => Some(options.clone()),
                _ => None,
            })
            .expect("the picker");
        assert_eq!(options, HARNESS_PRESETS.map(str::to_string).to_vec());
        assert!(!options.contains(&HARNESS_OFF.to_string()));
        assert!(!options.contains(&HARNESS_CUSTOM.to_string()));
    }
